function taskTransitionIssues(s,t,a){const errors={};const check=(message,path='_')=>errors[path]=message;if(a==='task-publish'&&(!str(t.title).trim()||!str(t.requirements||t.description).trim()))check('发布前需填写任务名称与要求');if(a==='task-publish'&&t.assignmentSnapshot?.status!=='active'&&t.assignmentSnapshot)check('任教关系已失效，请先核对任务关联','assignmentStatus');if(a==='task-publish'&&t.assignmentSnapshot&&t.audienceSnapshot&&[...t.audienceSnapshot.classIds,...t.audienceSnapshot.members.map(x=>x.classId)].some(id=>!id||!t.assignmentSnapshot.classIds.includes(id)))check('教学对象班级不在当前任教关系范围内','assignmentScope');if(a==='task-publish'&&t.dueAt&&dateNumber(t.dueAt)<=dateNumber(now(s)))check('发布任务的截止时间已过期');if(a==='task-start'&&t.prerequisiteIds.some(k=>s.value.tasks.find(x=>x.id===k)?.status!=='completed'))check('前置任务尚未完成');if(a==='task-complete'&&t.checklist.some(c=>c.required&&!c.done))check('请完成所有必需检查项');return errors}
function updateTaskReference(el,taskId,key,snapshot){const s=find(el);if(!s||s.type!=='teaching-task'||!isTeacher(s)||s.p.readonly||s.p.disabled||['readonly','disabled','forbidden'].includes(s.status))return false;const t=s.value.tasks.find(x=>x.id===taskId);if(!t||t.status!=='draft'||t.locked)return false;if(!snapshot||typeof snapshot!=='object')throw Error('任务关联快照必须为对象');if(key==='audienceSnapshot'){if(!Array.isArray(snapshot.classIds)||!Array.isArray(snapshot.studentIds)||!Array.isArray(snapshot.members))throw Error('教学对象快照缺少名单');ids(snapshot.members);snapshot.classIds.forEach(id=>ids([{id}]));snapshot.studentIds.forEach(id=>ids([{id}]))}if(key==='curriculumSnapshot'){if(!Array.isArray(snapshot.nodes)||!Number.isFinite(snapshot.totalHours)||snapshot.totalHours<=0)throw Error('教学目录快照学时或节点无效');ids(snapshot.nodes)}if(key==='assignmentSnapshot'){if(!idOK(snapshot.id)||!Array.isArray(snapshot.classIds)||!idOK(snapshot.teacherId)||!idOK(snapshot.courseId)||!idOK(snapshot.termId))throw Error('任教快照关联无效')}cancelSilent(s);t[key]=copy(snapshot);changed(s,'task-reference-change',{taskId,key,snapshot});draw(s);return true}
